import{_ as n,o as s,c as t,a4 as e}from"./chunks/framework.CAgiNEKA.js";const u=JSON.parse('{"title":"2026 AI 应用学习路线图：从入门到进阶，工具 + 提示词 + 资源一文打包","description":"","frontmatter":{},"headers":[],"relativePath":"ai-knowledge/ai-learning-roadmap-2026.md","filePath":"ai-knowledge/ai-learning-roadmap-2026.md","lastUpdated":1780054548000}'),r={name:"ai-knowledge/ai-learning-roadmap-2026.md"};function l(p,a,i,o,d,h){return s(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="_2026-ai-应用学习路线图-从入门到进阶-工具-提示词-资源一文打包" tabindex="-1">2026 AI 应用学习路线图：从入门到进阶，工具 + 提示词 + 资源一文打包 <a class="header-anchor" href="#_2026-ai-应用学习路线图-从入门到进阶-工具-提示词-资源一文打包" aria-label="Permalink to &quot;2026 AI 应用学习路线图：从入门到进阶，工具 + 提示词 + 资源一文打包&quot;">​</a></h1><blockquote><p>本文整理自以下来源：</p><ul><li><a href="https://zhuanlan.zhihu.com/p/2009594401647769546" target="_blank" rel="noreferrer">2026 最全 AI 应用学习路线图（万字长文）· 知乎</a></li><li><a href="https://zhuanlan.zhihu.com/p/2014767020277769613" target="_blank" rel="noreferrer">WaytoAGI 官网介绍 · 知乎</a></li></ul><p>原文观点仅代表作者个人意见。</p></blockquote><hr><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>AI 工具更新太快，信息量太大，很多人不知道从哪里下手——到底该学什么、用什么、看什么？</p><p>这篇文章把 2026 年 AI 学习的核心脉络梳理清楚：<strong>入门怎么走、提示词怎么写、进阶去哪找、平时看什么信息源</strong>，按顺序读完，基本上就有了一条清晰的路。</p><hr><h2 id="测评场景汇总" tabindex="-1">测评场景汇总 <a class="header-anchor" href="#测评场景汇总" aria-label="Permalink to &quot;测评场景汇总&quot;">​</a></h2><h3 id="_1-入门-提示词基础用法" tabindex="-1">1. 入门：提示词基础用法 <a class="header-anchor" href="#_1-入门-提示词基础用法" aria-label="Permalink to &quot;1. 入门：提示词基础用法&quot;">​</a></h3><p>刚开始用 AI，掌握三件事就够了：</p><p><strong>结论：</strong> 说清楚你要什么 + 给足背景信息 + 指定输出格式。这三点能解决 80% 的&quot;AI 没答到点上&quot;问题。</p><p><strong>示例对比：</strong></p><p>❌ 效果差：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我写一篇文章</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>✅ 效果好：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是一名科技媒体编辑，帮我写一篇面向普通用户的 AI 科普文章，</span></span>
<span class="line"><span>主题是&quot;什么是 Token&quot;，字数 800 字左右，语气轻松，</span></span>
<span class="line"><span>结尾加一个实用小技巧。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><hr><h3 id="_2-进阶-结构化提示词-langgpt-方法" tabindex="-1">2. 进阶：结构化提示词（LangGPT 方法） <a class="header-anchor" href="#_2-进阶-结构化提示词-langgpt-方法" aria-label="Permalink to &quot;2. 进阶：结构化提示词（LangGPT 方法）&quot;">​</a></h3><p><strong>结论：</strong> 如果你只学一个进阶技巧，推荐结构化提示词。最典型的是 <strong>LangGPT 方法</strong>，把一条提示词拆成几个模块：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 角色</span></span>
<span class="line"><span>你是一名资深的 Java 后端工程师</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 背景</span></span>
<span class="line"><span>我正在开发一个 Spring Boot 项目，需要接入 Claude API</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 任务</span></span>
<span class="line"><span>帮我写一个 Service 层的代码，实现流式调用 Claude 的功能</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 要求</span></span>
<span class="line"><span>- 使用 WebClient 实现 SSE 流式输出</span></span>
<span class="line"><span>- 加上错误处理和超时设置</span></span>
<span class="line"><span>- 代码注释用中文</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 输出格式</span></span>
<span class="line"><span>直接给出完整可运行的代码，不需要解释</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><p>这种写法的好处：条理清晰，AI 不容易理解偏，输出质量稳定，而且可以复用。</p><hr><h3 id="_3-高级技巧-多轮迭代-追问" tabindex="-1">3. 高级技巧：多轮迭代 + 追问 <a class="header-anchor" href="#_3-高级技巧-多轮迭代-追问" aria-label="Permalink to &quot;3. 高级技巧：多轮迭代 + 追问&quot;">​</a></h3><p><strong>结论：</strong> 很多高手的秘诀不是提示词写得多精妙，而是<strong>特别会追问</strong>。不要指望一次就得到完美答案，第一次给方向，后面几轮不断精炼。</p><p>常用追问模板：</p><ul><li>&quot;你刚才说的 X 部分，能更详细展开吗？&quot;</li><li>&quot;这个方案有什么潜在问题？&quot;</li><li>&quot;换一种风格/方式再来一版&quot;</li><li>&quot;假设我是完全不懂技术的用户，怎么解释这件事？&quot;</li></ul><hr><h3 id="_4-工具推荐-只收藏这一个知识库就够了" tabindex="-1">4. 工具推荐：只收藏这一个知识库就够了 <a class="header-anchor" href="#_4-工具推荐-只收藏这一个知识库就够了" aria-label="Permalink to &quot;4. 工具推荐：只收藏这一个知识库就够了&quot;">​</a></h3><p><strong>WaytoAGI</strong>（<a href="https://waytoagi.com" target="_blank" rel="noreferrer">waytoagi.com</a>）— 目前中文圈最全面的 AI 开源知识库，涵盖：</p><ul><li>基础概念 → 提示词工程 → AI 实战案例，层层递进</li><li>&quot;提示词宝库&quot;：大量经过验证的高质量模板，可直接复用</li><li>每日更新精选文章，国内外 AI 动态都有</li><li>内置 AI 问答助手，直接问问题就能找到答案</li></ul><p>使用技巧：善用飞书文档内的搜索，直接搜你想了解的工具名或场景关键词。</p><hr><h3 id="_5-信息源推荐-日常跟进-ai-动态" tabindex="-1">5. 信息源推荐：日常跟进 AI 动态 <a class="header-anchor" href="#_5-信息源推荐-日常跟进-ai-动态" aria-label="Permalink to &quot;5. 信息源推荐：日常跟进 AI 动态&quot;">​</a></h3><p>入门阶段不需要关注太多，先订上这几个保持信息敏感度：</p><table tabindex="0"><thead><tr><th>来源</th><th>类型</th><th>特点</th></tr></thead><tbody><tr><td><strong>量子位</strong></td><td>公众号</td><td>国内 AI 资讯最快，覆盖广</td></tr><tr><td><strong>机器之心</strong></td><td>公众号</td><td>技术向，深度报道多</td></tr><tr><td><strong>赛博禅心</strong></td><td>公众号/知乎</td><td>独立观点，适合思考型读者</td></tr><tr><td><strong>歸藏的AI工具箱</strong></td><td>公众号</td><td>工具测评，实用为主</td></tr><tr><td><strong>Agent橘</strong></td><td>知乎/公众号</td><td>专注 Agent 方向，2026 年必看</td></tr></tbody></table><hr><h3 id="_6-费用参考-用-ai-学-ai-成本极低" tabindex="-1">6. 费用参考（用 AI 学 AI，成本极低） <a class="header-anchor" href="#_6-费用参考-用-ai-学-ai-成本极低" aria-label="Permalink to &quot;6. 费用参考（用 AI 学 AI，成本极低）&quot;">​</a></h3><p>学习阶段用 Claude 或 ChatGPT，无需大量 API 调用，主要是对话，成本极低。如果通过 API 平台接入：</p><table tabindex="0"><thead><tr><th>用途</th><th>推荐模型</th><th>月均成本</th></tr></thead><tbody><tr><td>日常提问、学习</td><td>Claude Sonnet</td><td>&lt; $5</td></tr><tr><td>写代码、做项目</td><td>Claude Sonnet</td><td>$10-30</td></tr><tr><td>复杂架构设计</td><td>Claude Opus（少量）</td><td>$20-50</td></tr></tbody></table><hr><h2 id="原文总结" tabindex="-1">原文总结 <a class="header-anchor" href="#原文总结" aria-label="Permalink to &quot;原文总结&quot;">​</a></h2><p>AI 学习没有捷径，但有节奏：<strong>先把提示词基础用顺 → 再学结构化写法 → 然后练追问迭代的习惯 → 最后找到自己信任的信息源保持更新</strong>。</p><p>工具会变，模型会更新，但&quot;说清楚需求、不断迭代&quot;这个底层逻辑不会过时。</p><hr><h2 id="🐼-熊猫算力视角-怎么选适合新手的入口" tabindex="-1">🐼 熊猫算力视角：怎么选适合新手的入口？ <a class="header-anchor" href="#🐼-熊猫算力视角-怎么选适合新手的入口" aria-label="Permalink to &quot;🐼 熊猫算力视角：怎么选适合新手的入口？&quot;">​</a></h2><ul><li>刚入门、不想折腾：直接用熊猫算力平台对话界面，国内直连，零配置</li><li>有一点技术基础：申请 API Key，接入 Cherry Studio 或 Chatbox，体验更好</li><li>开发者：接 API，搭配 Claude Code，从第一行代码开始就用 AI 提效</li></ul><p>👉 <a href="https://pandatoken.cn" target="_blank" rel="noreferrer">熊猫算力新手指引 →</a></p>`,47)])])}const b=n(r,[["render",l]]);export{u as __pageData,b as default};
